<script lang="ts">
 import {onMount,untrack} from 'svelte';
 import type {Revision} from '../application/publishing';
 import type {ReaderGateway,Manifest} from '$lib/features/reading/application/reader';
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {publicationStates,preparationLabel} from './messages';
 import Icon from '$lib/shared/presentation/ui/Icon.svelte';
 let {item,reader,busy,onback,onpublish,onreject}:{item:Revision;reader?:ReaderGateway;busy:boolean;onback:()=>void;onpublish:()=>void;onreject:()=>void}=$props();
 const {locale}=useLocale();const states=$derived(publicationStates($locale));
 let manifest=$state<Manifest|null>(null),loading=$state(false),failed=$state(false),imageFailed=$state(false),position=$state(0),zoom=$state(100),mounted=$state(false);let generation=0;
 const current=$derived(manifest?.pages[position]);
 const fragments=$derived(current?(['high','standard','eco'] as const).map(tier=>current.variants[tier]).find(value=>value?.length)||[]:[]);
 const ready=$derived(item.pages.length>0&&item.pages.every(page=>page.status==='ready'));
 async function load(){if(!reader)return;const run=++generation;loading=true;failed=false;imageFailed=false;manifest=null;try{const result=await reader.manifest(item.releaseId,item.id);if(run===generation)manifest=result;}catch{if(run===generation)failed=true;}finally{if(run===generation)loading=false;}}
 $effect(()=>{item.id;if(mounted)untrack(()=>{position=0;zoom=100;void load();});});
 onMount(()=>{mounted=true;return()=>{generation++;};});
 function change(value:number){position=value;imageFailed=false;}
</script>
<div class="review-heading"><div><h1>{item.titleName} · {text($locale,'Тарау ','Глава ')+item.chapterLabel}</h1><p>{text($locale,'Осы аударма мен оның нұсқасын тексеру.','Проверка конкретного перевода и его версии.')}</p></div><button class="button subtle" disabled={busy} onclick={onback}>{text($locale,'Кезекке','В очередь')}</button></div>
<div class="review-badges"><span>{item.teamName}</span><span>{text($locale,'Нұсқа','Версия')} {item.id.slice(0,8)}</span><span>{states[item.state]||item.state}</span></div>
<div class="publication-review">
 <section class="review-canvas" aria-label={text($locale,'Аударма беттері','Страницы перевода')}><header><strong>{text($locale,'Аударма беттері','Страницы перевода')}</strong><div class="zoom"><button aria-label={text($locale,'Кішірейту','Уменьшить')} disabled={zoom<=50} onclick={()=>zoom-=25}>−</button><span>{zoom}%</span><button aria-label={text($locale,'Үлкейту','Увеличить')} disabled={zoom>=200} onclick={()=>zoom+=25}>+</button></div></header>
  <div class="review-image" style:--zoom={zoom+'%'}>{#if loading}<p role="status">{text($locale,'Беттер жүктелуде…','Загружаем страницы…')}</p>{:else if failed}<div role="alert"><p>{text($locale,'Алдын ала көрініс жүктелмеді.','Не удалось загрузить предпросмотр.')}</p><button class="button subtle" onclick={()=>load()}>{text($locale,'Қайталау','Повторить')}</button></div>{:else if current}<div class="page-fragments">{#each fragments as fragment,index (fragment.id)}<img src={fragment.url} alt={index===0?text($locale,(position+1)+'-бет','Страница '+(position+1)):''} onerror={()=>imageFailed=true}/>{/each}</div>{#if imageFailed}<p role="alert">{text($locale,'Сурет жүктелмеді. Читалкада қайта тексеріңіз.','Изображение не загрузилось. Проверь в читалке.')}</p>{/if}{:else if item.pages[position]?.thumbnailId}<img class="thumbnail-preview" src={'/api/v1/media/'+encodeURIComponent(item.pages[position].thumbnailId||'')} alt={text($locale,'Бет миниатюрасы','Миниатюра страницы')}/>{:else}<p>{text($locale,'Алдын ала көрініс жоқ','Нет предпросмотра')}</p>{/if}</div>
  <footer><div class="page-controls"><button class="button subtle" aria-label={text($locale,'Алдыңғы бет','Предыдущая страница')} disabled={position===0} onclick={()=>change(position-1)}><Icon name="left" size={16}/></button><label>{text($locale,'Бет','Страница')}<select value={position} onchange={event=>change(Number(event.currentTarget.value))}>{#each manifest?.pages||item.pages as _,index}<option value={index}>{index+1}</option>{/each}</select></label><span>{text($locale,'/ ','из ')}{manifest?.pages.length||item.pages.length}</span><button class="button subtle" aria-label={text($locale,'Келесі бет','Следующая страница')} disabled={position+1>=(manifest?.pages.length||item.pages.length)} onclick={()=>change(position+1)}><Icon name="right" size={16}/></button></div><a href={'/read/'+encodeURIComponent(item.releaseId)+'?preview='+encodeURIComponent(item.id)+'&returnTo='+encodeURIComponent('/admin/moderation?revision='+item.id)}>{text($locale,'Читалкада ашу','Открыть в читалке')} ↗</a></footer>
 </section>
 <aside class="review-inspector"><section><h2>{text($locale,'Аударма','Перевод')}</h2><dl><div><dt>{text($locale,'Команда','Команда')}</dt><dd>{item.teamName}</dd></div><div><dt>{text($locale,'Нұсқа ID','ID версии')}</dt><dd>{item.id}</dd></div><div><dt>{text($locale,'Дайындау','Подготовка')}</dt><dd>{preparationLabel($locale,item.preparationMethod)}</dd></div></dl></section>
 <section><h2>{text($locale,'Жариялауға дайындық','Готовность к публикации')}</h2><ul><li>{ready?'✓':'!'} {text($locale,'Өңделген беттер','Обработанные страницы')}: {item.pages.filter(page=>page.status==='ready').length} / {item.pages.length}</li><li>{item.source&&item.credits?'✓':'!'} {text($locale,'Дереккөз және кредиттер','Источник и кредиты')}</li><li>{item.rightsConfirmed?'✓':'!'} {text($locale,'Құқық расталған','Подтверждение прав')}</li></ul></section>
 <section><h2>{text($locale,'Дереккөз және кредиттер','Источник и кредиты')}</h2><p>{item.source||'—'}</p><p>{item.credits||'—'}</p><p>{item.humanReviewed?text($locale,'Команда: адам тексерген','Команда: проверено человеком'):text($locale,'Адам тексеруі көрсетілмеген','Проверка человеком не заявлена')}</p>{#if item.humanReviewer}<p>{item.humanReviewer}</p>{/if}</section></aside>
</div>
<div class="review-decision"><div><strong>{item.teamName} · {text($locale,'Тарау ','Глава ')+item.chapterLabel}</strong><p>{text($locale,'Шешім тек осы аударма нұсқасына қатысты.','Решение относится только к этой версии перевода.')}</p></div>{#if item.state==='submitted'}<div class="decision-buttons"><button class="button subtle" disabled={busy} onclick={onreject}>{text($locale,'Түзетуге қайтару','Вернуть на исправление')}</button><button class="button primary" disabled={busy||!item.rightsConfirmed||!ready} onclick={onpublish}>{text($locale,'Жариялап, жалғастыру','Опубликовать и далее')}</button></div>{:else}<p>{states[item.state]||item.state}</p>{/if}</div>
<style>
 .review-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:24px}.review-heading h1{font-size:28px}.review-heading p{font-size:14px;color:var(--muted);margin-top:8px}.review-badges{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:24px}.review-badges span{padding:6px 9px;background:var(--raised);border-radius:6px;font-size:12px}.publication-review{display:grid;gap:20px;min-width:0}.review-canvas,.review-inspector section{border:1px solid var(--line);border-radius:12px;background:var(--panel);min-width:0;overflow:hidden}.review-canvas header,.review-canvas footer{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:12px 16px;font-size:13px}.zoom{display:flex;align-items:center;gap:8px}.zoom button{min-width:44px;min-height:44px;background:none;color:var(--muted);border:0}.review-image{background:var(--bg);height:480px;max-height:65dvh;overflow:auto;display:flex;flex-direction:column;align-items:center;padding:12px;color:var(--muted)}.page-fragments{width:var(--zoom);flex:none;max-width:none}.page-fragments img{display:block;width:100%;height:auto}.thumbnail-preview{max-width:100%;height:100%;object-fit:contain}.review-inspector{display:grid;gap:16px;align-content:start;min-width:0}.review-inspector section{padding:20px 24px}.review-inspector h2{font-size:17px;margin-bottom:16px}.review-inspector p{font-size:13px;color:var(--muted);white-space:pre-wrap;overflow-wrap:anywhere;margin-top:10px}dl{margin:0;display:grid;gap:12px}dl>div{display:flex;justify-content:space-between;gap:16px;min-width:0}dt{font-size:13px;color:var(--muted)}dd{font-size:13px;overflow-wrap:anywhere;min-width:0;margin:0;text-align:right;max-width:60%}ul{list-style:none;padding:0;margin:0;display:grid;gap:12px;font-size:13px;color:var(--muted)}.page-controls{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.page-controls label{display:flex;align-items:center;gap:6px}.page-controls select{width:70px;font-size:13px}.page-controls .button{padding:6px}.review-decision{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;position:sticky;bottom:12px;z-index:5;background:var(--raised);border:1px solid var(--line);border-radius:12px;padding:16px;margin-top:24px;box-shadow:0 6px 24px #0003;font-size:13px}.review-decision p{font-size:12px;color:var(--muted);margin-top:4px}.decision-buttons{display:flex;gap:12px;flex-wrap:wrap}.review-decision .button{font-size:13px}@media(min-width:1100px){.publication-review{grid-template-columns:minmax(0,2fr) minmax(300px,1fr)}}@media(max-width:639px){.review-heading h1{font-size:22px}.review-decision{position:static}.decision-buttons{width:100%}.decision-buttons .button{flex:1}.review-inspector section{padding:16px}}
</style>
